-- Merge workflow-local input definitions without replacing IDs or custom settings.
-- Exact replays make no writes. New variables append after existing/custom order.
DO $workflow_variable_seed$
DECLARE
    seed_row RECORD;
    existing_row application.workflow_stage_variable%ROWTYPE;
    next_order INTEGER;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('application.workflow_stage_variable.reference_seed', 0)
    );
    FOR seed_row IN
        SELECT stage.workflow_stage_id, seed.*
FROM (VALUES
    ('analysis', 'one_shot', 'relationship_inference', 'source_context', 'workflow.analysis.common.relationship_inference.inputs.source_context', 'json', 'Unique contributing source Connections and business context.', '[{"tenant_code":"ACME","tenant_description":"Wholesale distribution business.","system_code":"ERP","system_description":"Manages sales orders and billing.","system_type_code":"ERP","system_type_description":"Systems for managing core business operations.","connection_code":"ERP_SOURCE","connection_description":null,"connection_type_code":"SQL_SERVER","connection_type_description":"Connection to a Microsoft SQL Server database.","zone_code":"source","zone_description":"Originating source data."}]'::jsonb, 10),
