    ('analysis', 'one_shot', 'relationship_inference', 'object_attribute_context', 'workflow.analysis.common.relationship_inference.inputs.object_attribute_context', 'json', 'Eligible Attributes grouped by physical Object, with current saved descriptions, types, flags, and Profiles. Descriptions, inferred types and is_natural_key/is_primary_key/is_nullable/is_pii are current Model enrichment. NULL means unknown, not false. Multiple true key flags identify members of the chosen composite key, not independently unique columns. attribute_nullability and is_masking_required remain registered physical metadata. profile contains saved counts, percentages, lengths and measurement scope; batch profiles cannot establish whole-table uniqueness or non-nullability. PII is an inferred classification and must not weaken registered masking requirements.', '[{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders","attributes":[{"attribute_name":"CustomerCode","attribute_description":"ERP customer account that placed this order.","attribute_data_type":"VARCHAR","attribute_inferred_data_type":"VARCHAR","attribute_nullability":false,"is_natural_key":false,"is_surrogate_key":false,"is_masking_required":false,"is_meta_data":false,"profile":{"profiled_at":"2026-09-07T14:30:00Z","row_scope":"all_rows","batch_attribute_name":null,"batch_id":null,"row_count":1000,"non_null_count":1000,"null_count":0,"blank_count":0,"distinct_count":100,"min_data_length":6,"max_data_length":6,"avg_data_length":6,"percent_populated":100,"percent_duplicates":90,"percent_null":0,"percent_blank":0,"percent_distinct":10},"is_primary_key":null,"is_nullable":null,"is_pii":null}],"selected_attribute_names":["CustomerCode"]},{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Customers","attributes":[{"attribute_name":"CustomerCode","attribute_description":"Business identifier of this ERP customer account.","attribute_data_type":"VARCHAR","attribute_inferred_data_type":"VARCHAR","attribute_nullability":false,"is_natural_key":true,"is_surrogate_key":false,"is_masking_required":false,"is_meta_data":false,"profile":{"profiled_at":"2026-09-07T14:30:00Z","row_scope":"all_rows","batch_attribute_name":null,"batch_id":null,"row_count":100,"non_null_count":100,"null_count":0,"blank_count":0,"distinct_count":100,"min_data_length":6,"max_data_length":6,"avg_data_length":6,"percent_populated":100,"percent_duplicates":0,"percent_null":0,"percent_blank":0,"percent_distinct":100},"is_primary_key":null,"is_nullable":null,"is_pii":null}],"selected_attribute_names":["CustomerCode"]}]'::jsonb, 40),
    ('analysis', 'one_shot', 'relationship_inference', 'ingestion_mapping', 'workflow.analysis.common.relationship_inference.inputs.ingestion_mapping', 'json', 'Registered Object-only source-to-selected-target links.', '[{"source":{"tenant_code":"ACME","system_code":"ERP","connection_code":"ERP_SOURCE","object_schema":"sales","object_name":"SalesOrder","object_description":"Sales orders created in ERP; one row per order."},"target":{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders"}},{"source":{"tenant_code":"ACME","system_code":"ERP","connection_code":"ERP_SOURCE","object_schema":"sales","object_name":"Customer","object_description":"ERP customer accounts; one row per customer account."},"target":{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Customers"}}]'::jsonb, 50),
    ('analysis', 'one_shot', 'relationship_inference', 'object_relationship_context', 'workflow.analysis.common.relationship_inference.inputs.object_relationship_context', 'json', 'Existing applied relationships touching each scoped physical Object. Incoming matches the to-Object; outgoing matches the from-Object. Include empty groups. Preserve endpoint, hypothesis, lifecycle, lock and recorded validation fields. Validation outcome and aggregate counts are saved evidence, not a fresh measurement; all-null validation fields mean unvalidated. An endpoint outside object_context is contextual only and does not become an eligible authoring source.', '[{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders","incoming_relationships":[],"outgoing_relationships":[{"from_tenant_code":"GDS","from_system_code":"WAREHOUSE","from_connection_code":"MAIN","from_object_schema":"bronze","from_object_name":"Orders","to_tenant_code":"GDS","to_system_code":"WAREHOUSE","to_connection_code":"MAIN","to_object_schema":"bronze","to_object_name":"Customers","from_attribute_name":"CustomerCode","to_attribute_name":"CustomerCode","relationship_kind":"reference","relationship_confidence":"high","relationship_basis":"The source definition identifies the order''s customer account.","inferred_cardinality":"many_to_one","analysis_result_status":"active","analysis_result_is_locked":false,"validation_policy_version":"1.0.0","validation_result":"supported","validation_source_non_null_count":20,"validation_source_distinct_count":10,"validation_target_non_null_count":10,"validation_target_distinct_count":10,"validation_source_missing_target_count":0,"validation_unused_target_count":0,"validation_duplicate_target_key_count":0}]},{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Customers","incoming_relationships":[{"from_tenant_code":"GDS","from_system_code":"WAREHOUSE","from_conne