    ('analysis', 'tool_assisted', 'relationship_inference', 'modeling_assertions', 'workflow.analysis.common.relationship_inference.inputs.modeling_assertions', 'json', 'Active assertions from active documents in authorized Model/System scope, available automatically to all downstream workflows. Determine relevance from the statement and task, not legacy layer flags. record_type is a free-text classification of facts, definitions, relationships, conventions, constraints or requirements. text is the statement; details.notes adds context, examples and exceptions. Other details may contain formula, grain, dimensions, date_basis, exclusions, history or acceptance_criteria; missing details are unspecified. document_name and source_location identify provenance. confidence is evidence confidence, not priority. Keys link model support to assertions; they are not physical lineage or proof of source data.', '[{"modeling_assertion_record_key":"order_customer_reference","modeling_assertion_document_name":"ERP relationship notes","modeling_assertion_record_type":"relationship","modeling_assertion_text":"Within this ERP source, Orders.CustomerCode references the customer account identified by Customers.CustomerCode.","modeling_assertion_details":{"from":{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders","attribute_name":"CustomerCode"},"to":{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Customers","attribute_name":"CustomerCode"}},"modeling_assertion_source_location":{"section":"Orders and customers"},"modeling_assertion_confidence":"high"}]'::jsonb, 70),
    ('code_generation', NULL, 'sql_generation', 'mapping_templates', 'workflow.code_generation.common.sql_generation.inputs.mapping_templates', 'json', 'Deduplicated definitions of templates used by the applied Object and Attribute transformations. Match output_template_code to code; ordered fields explain their meaning, types, examples and requirements. Inactive saved templates still describe their documents. An empty list in older frozen context means definitions were not supplied, not that a different template may be assumed.', '[{"code":"mapping_logical_object_default","name":"Default Logical Object Mapping","description":"Logical Object Mapping using the agreed source, transformation and null-handling fields.","target_type":"mapping_object","modeled_entity_type":"logical_entity","is_active":true,"fields":[{"name":"source_tables","description":"Required non-null array; [] is allowed. Each physical source has tenant_code, system_code, connection_code, object_schema, object_name. Logical lookup sources have entity_type=logical_entity, entity_schema_name, entity_name. Use only eligible frozen sources. No alias field is required; explain join roles in the sample query when needed.","data_type":"array","array_item_type":"object","is_required":true,"order":1,"example":[{"tenant_code":"NWA","system_code":"GDS","connection_code":"lakehouse","object_schema":"bronze_crm","object_name":"customer"}]},{"name":"filter_criteria","description":"Required field, nullable text. Object-level filters; null when no filter applies.","data_type":"string","array_item_type":null,"is_required":true,"order":2,"example":"Keep active customer records."},{"name":"sample_query","description":"Required field, nullable text. Pseudo-SQL illustrating supported source joins, predicates, filters and transformations. Null when unavailable; do not invent missing rules.","data_type":"string","array_item_type":null,"is_required":true,"order":3,"example":"SELECT * FROM bronze_crm.customer WHERE is_active = true"}]},{"code":"mapping_logical_attribute_default","name":"Default Logical Attribute Mapping","description":"Logical Attribute Mapping using the agreed source, transformation and null-handling fields.","target_type":"mapping_attribute","modeled_entity_type":"logical_entity","is_active":true,"fields":[{"name":"transformation_logic","description":"Required field, nullable text. Attribute-level natural-language or pseudocode transformation suitable for SQL generation; null when unsupported or not applicable.","data_type":"string","array_item_type":null,"is_required":true,"order":1,"example":"Trim whitespace from the source customer name."},{"name":"default_record","description":"Required field, nullable text. Default value or fallback logic to use when the input is null. Null means do nothing; do not invent a replacement.","data_type":"string","array_item_type":null,"is_required":true,"order":2,"example":null},{"name":"source_columns","description":"Required field, nullable array; [] is allowed. Each physical source has tenant_code, system_code, connection_code, object_schema, object_name. Logical lookup sources have entity_type=logical_entity, entity_schema_name, entity_name. Each source also has attribute_name. Use only eligible frozen Attributes. Null when not specified.","data_type":"array","array_item_type":"object","is_required":true,"order":3,"example":[{"tenant_code":"NWA","system_code":"GDS","connection_code":"lakehouse","object_schema":"bronze_crm","object_name":"customer","attribute_name":"customer_name"}]}]}]'::jsonb, 10),
