    ('dimensional', 'one_shot', 'candidate_authoring', 'audit_columns', 'workflow.dimensional.common.candidate_authoring.inputs.audit_columns', 'json', 'Effective Gold audit template; blank settings resolve to shared audit defaults; an explicit empty columns array disables audits. Reserve effective names for framework Attributes; source/business fields need distinct names. Same schema_version/ordered columns layout as Logical audit settings. Each column has semantic_name, data_type, nullable, definition. Configured audit columns remain authoritative.', '{"schema_version":"1.0","columns":[{"semantic_name":"LoadedAt","data_type":"TIMESTAMP","nullable":false,"definition":"Warehouse load time."}]}'::jsonb, 250),
    ('dimensional', 'one_shot', 'candidate_authoring', 'technical_columns', 'workflow.dimensional.common.candidate_authoring.inputs.technical_columns', 'json', 'Effective GoldTechnicalPolicy (standard keys/history fields when unset): schema_version, dimension_surrogate_key, fact_bridge_foreign_key, type_2. Do not add guessed policy fields. The current backend projects technical/surrogate/foreign-key/audit Attributes.', '{"schema_version":"1.0","dimension_surrogate_key":{"semantic_name_template":"{entity_name}Key","data_type":"BIGINT","nullable":false,"definition_template":"Surrogate key for {entity_name}."},"fact_bridge_foreign_key":{"with_role_semantic_name_template":"{role_name}Key","without_role_semantic_name_template":"{entity_name}Key","definition_template":"Foreign key to {entity_name} for {role_name}."},"type_2":{"effective_from":{"semantic_name":"EffectiveFrom","data_type":"TIMESTAMP","nullable":false,"definition":"Start of this version validity."},"effective_to":{"semantic_name":"EffectiveTo","data_type":"TIMESTAMP","nullable":true,"definition":"End of validity; null for current version."},"is_current":{"semantic_name":"IsCurrent","data_type":"BOOLEAN","nullable":false,"definition":"Whether this is the current version."}}}'::jsonb, 260),
