    ('mapping', 'one_shot', 'mapping_authoring', 'object_output_template', 'workflow.mapping.common.mapping_authoring.inputs.object_output_template', 'json', 'Selected Object transformation template by nominal code with description, typed ordered fields, required flags and examples; null means no selected template. Guidance does not change the fixed outer output schema.', '{"code":"mapping_logical_object_default","name":"Default Logical Object Mapping","description":"Logical Object Mapping using the agreed source, transformation and null-handling fields.","target_type":"mapping_object","modeled_entity_type":"logical_entity","is_active":true,"fields":[{"name":"source_tables","description":"Required non-null array; [] is allowed. Each physical source has tenant_code, system_code, connection_code, object_schema, object_name. Logical lookup sources have entity_type=logical_entity, entity_schema_name, entity_name. Use only eligible frozen sources. No alias field is required; explain join roles in the sample query when needed.","data_type":"array","array_item_type":"object","is_required":true,"order":1,"example":[{"tenant_code":"NWA","system_code":"GDS","connection_code":"lakehouse","object_schema":"bronze_crm","object_name":"customer"}]},{"name":"filter_criteria","description":"Required field, nullable text. Object-level filters; null when no filter applies.","data_type":"string","array_item_type":null,"is_required":true,"order":2,"example":"Keep active customer records."},{"name":"sample_query","description":"Required field, nullable text. Pseudo-SQL illustrating supported source joins, predicates, filters and transformations. Null when unavailable; do not invent missing rules.","data_type":"string","array_item_type":null,"is_required":true,"order":3,"example":"SELECT * FROM bronze_crm.customer WHERE is_active = true"}]}'::jsonb, 90),
