    ('mapping', 'tool_assisted', 'mapping_authoring', 'attribute_output_template', 'workflow.mapping.common.mapping_authoring.inputs.attribute_output_template', 'json', 'Selected Attribute transformation template by nominal code with description, typed ordered fields, required flags and examples; null means no selected template.', '{"code":"mapping_logical_attribute_default","name":"Default Logical Attribute Mapping","description":"Logical Attribute Mapping using the agreed source, transformation and null-handling fields.","target_type":"mapping_attribute","modeled_entity_type":"logical_entity","is_active":true,"fields":[{"name":"transformation_logic","description":"Required field, nullable text. Attribute-level natural-language or pseudocode transformation suitable for SQL generation; null when unsupported or not applicable.","data_type":"string","array_item_type":null,"is_required":true,"order":1,"example":"Trim whitespace from the source customer name."},{"name":"default_record","description":"Required field, nullable text. Default value or fallback logic to use when the input is null. Null means do nothing; do not invent a replacement.","data_type":"string","array_item_type":null,"is_required":true,"order":2,"example":null},{"name":"source_columns","description":"Required field, nullable array; [] is allowed. Each physical source has tenant_code, system_code, connection_code, object_schema, object_name. Logical lookup sources have entity_type=logical_entity, entity_schema_name, entity_name. Each source also has attribute_name. Use only eligible frozen Attributes. Null when not specified.","data_type":"array","array_item_type":"object","is_required":true,"order":3,"example":[{"tenant_code":"NWA","system_code":"GDS","connection_code":"lakehouse","object_schema":"bronze_crm","object_name":"customer","attribute_name":"customer_name"}]}]}'::jsonb, 100),
    ('mapping', 'tool_assisted', 'mapping_authoring', 'mapping_support_records', 'workflow.mapping.common.mapping_authoring.inputs.mapping_support_records', 'json', 'Individually pageable saved evidence envelopes with evidence_type and record. Includes target lineage/relationships, Analysis, Profiles and applicable Assertions; eligible upstream Logical definitions, Attributes/key roles, relationships, applied Object/Attribute Mapping documents and their available template definitions. Gold also includes active physical lineage descriptions, Profiles and Analysis restricted to this Model and business System. Physical evidence explains Logical inputs; it does not make raw Objects eligible Gold sources. Preserve opaque Mapping documents and exact schema-qualified identities; a missing template definition does not authorize guessing custom field semantics. Empty records mean no saved evidence.', '[]'::jsonb, 110),
    ('mapping', 'tool_assisted', 'mapping_authoring', 'mapping_support', 'workflow.mapping.common.mapping_authoring.inputs.mapping_support', 'json', 'Saved evidence scoped to this target and eligible sources: attribute_lineage links modeled names to physical source Attributes or assertion keys, with rationale and key roles; modeled_relationships describe conceptual join intent, not physical join proof; source_relationships carry Analysis confidence and measured validation when available; profiles are saved aggregate counts, percentages and lengths, not live rows or guaranteed current observations; assertions contain active Model/System context automatically without requiring Entity links or matching legacy layer flags. Evaluate relevance to this Entity; assertions are not proof of available sources. Keys identify provenance; free-text type and statement distinguish intent from facts. details may include notes, formula, grain, dimensions, date_basis, exclusions, history and acceptance_criteria when supplied. Missing details are unspecified. Empty lists mean no saved evidence, never permission to invent rules.', '{"attribute_lineage":[],"modeled_relationships":[],"source_relationships":[],"profiles":[],"assertions":[]}'::jsonb, 120),
