    ('metadata_enrichment_attribute', 'one_shot', 'candidate_authoring', 'gds_context', 'workflow.metadata_enrichment_attribute.common.candidate_authoring.inputs.gds_context', 'json', 'GDS Connection/zone placements for selected physical inputs or the Model-assigned placement of modeled Entity outputs.', '[{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","zone_code":"bronze","zone_description":"Stores ingested source data."}]'::jsonb, 20),
    ('metadata_enrichment_attribute', 'one_shot', 'candidate_authoring', 'object_context', 'workflow.metadata_enrichment_attribute.common.candidate_authoring.inputs.object_context', 'json', 'Selected physical Objects with current saved descriptions.', '[{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders","object_description":"Sales orders; one row represents one order.","zone_code":"bronze"}]'::jsonb, 30),
    ('metadata_enrichment_attribute', 'one_shot', 'candidate_authoring', 'object_attribute_context', 'workflow.metadata_enrichment_attribute.common.candidate_authoring.inputs.object_attribute_context', 'json', 'Eligible Attributes grouped by physical Object, with current saved descriptions, types, flags, and Profiles. Descriptions, inferred types and is_natural_key/is_primary_key/is_nullable/is_pii are current Model enrichment. NULL means unknown, not false. Multiple true key flags identify members of the chosen composite key, not independently unique columns. attribute_nullability and is_masking_required remain registered physical metadata. profile contains saved counts, percentages, lengths and measurement scope; batch profiles cannot establish whole-table uniqueness or non-nullability. PII is an inferred classification and must not weaken registered masking requirements.', '[{"tenant_code":"GDS","system_code":"WAREHOUSE","connection_code":"MAIN","object_schema":"bronze","object_name":"Orders","attributes":[{"attribute_name":"CustomerCode","attribute_description":"ERP customer account that placed this order.","attribute_data_type":"VARCHAR","attribute_inferred_data_type":"VARCHAR","attribute_nullability":false,"is_natural_key":false,"is_surrogate_key":false,"is_masking_required":false,"is_meta_data":false,"profile":{"profiled_at":"2026-09-07T14:30:00Z","row_scope":"all_rows","batch_attribute_name":null,"batch_id":null,"row_count":1000,"non_null_count":1000,"null_count":0,"blank_count":0,"distinct_count":100,"min_data_length":6,"max_data_length":6,"avg_data_length":6,"percent_populated":100,"percent_duplicates":90,"percent_null":0,"percent_blank":0,"percent_distinct":10},"is_primary_key":null,"is_nullable":null,"is_pii":null},{"attribute_name":"OrderID","attribute_description":"Business identifier of this ERP sales order.","attribute_data_type":"VARCHAR","attribute_inferred_data_type":"VARCHAR","attribute_nullability":false,"is_natural_key":true,"is_surrogate_key":